import openpyxl, docx, pymupdf as fitz, glob

def dump_xlsx(path, out):
    out.write(f'\n==================== XLSX: {path} ====================\n')
    wb = openpyxl.load_workbook(path, data_only=True)
    for name in wb.sheetnames:
        out.write(f'--- Sheet: {name} ---\n')
        ws = wb[name]
        for r_idx, row in enumerate(ws.iter_rows(values_only=True), 1):
            if any(v is not None for v in row):
                out.write(f'R{r_idx}: ' + ' | '.join(str(v) if v is not None else '' for v in row) + '\n')

def dump_docx(path, out):
    out.write(f'\n==================== DOCX: {path} ====================\n')
    d = docx.Document(path)
    for p in d.paragraphs:
        if p.text.strip():
            out.write(p.text + '\n')
    for t in d.tables:
        for row in t.rows:
            out.write(' | '.join(c.text.strip().replace('\n', ' ') for c in row.cells) + '\n')

def dump_pdf(path, out):
    out.write(f'\n==================== PDF: {path} ====================\n')
    doc = fitz.open(path)
    for i, page in enumerate(doc):
        out.write(f'--- Page {i+1} ---\n')
        out.write(page.get_text() + '\n')

with open('/tmp/other_records.txt', 'w') as out:
    for p in sorted(glob.glob('/filesystem/**/*.xlsx', recursive=True)):
        dump_xlsx(p, out)
    for p in sorted(glob.glob('/filesystem/**/*.docx', recursive=True)):
        dump_docx(p, out)
    for p in sorted(glob.glob('/filesystem/**/*.eml', recursive=True)):
        out.write(f'\n==================== EML: {p} ====================\n')
        with open(p) as ef:
            out.write(ef.read() + '\n')
    for p in ['/filesystem/Design-Drafting/Phase 3/DSR_Ph3_FinalMap_FM-26-100290_checkprint.pdf',
              '/filesystem/Tenders-Contracts/DSR_CCRs_CommonArea_Exhibit.pdf']:
        dump_pdf(p, out)
print('Done. Lines:', sum(1 for _ in open('/tmp/other_records.txt')))
"

